import{z as s,x as A,o as r,c as p,q as o,j as B,D as n,d as e,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"直接与间接破产成本","description":"","frontmatter":{"title":"直接与间接破产成本","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bankruptcy-direct-indirect.md","filePath":"econ/bankruptcy-direct-indirect.md","lastUpdated":1791063341000}'),d={name:"econ/bankruptcy-direct-indirect.md"};function c(D,a,m,u,h,f){const t=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="直接与间接破产成本" tabindex="-1">直接与间接破产成本 <a class="header-anchor" href="#直接与间接破产成本" aria-label="Permalink to &quot;直接与间接破产成本&quot;">​</a></h1><div class="epigraph"><p>法律费用可以很小，而客户、雇员与投资机会在违约前就已经离开；权衡里的「成本」必须拆开写。</p><footer>—— Warner, Bankruptcy Costs: Some Evidence, Journal of Finance 1977；Andrade and Kaplan, How Costly is Financial (Not Economic) Distress?, Journal of Finance 1998</footer></div><p>定位：<a href="/econ/tradeoff-capital">上一课</a>。税盾对困境成本已经给出内部 \\(D^\\ast\\)，并把困境写成一项现值。本课缺口是把这项拆成直接与间接：法庭与专业费用是一回事，经营与激励扭曲是另一回事。不重算 \\(\\tau_c D\\)，不把优序提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若破产成本只是律师费与管理人报酬，Warner（1977）对铁路破产的度量给出一个刺耳的数：直接成本相对公司价值往往很小。税盾若按 \\(\\tau_c D\\) 的量级，直接成本单独撑不起观察到的内部股权——权衡会仍偏向高杠杆。因此「PV(困境成本)」必须有一块不进法庭账单的。</p><p>间接成本在违约前就开始：客户不敢下长期订单，雇员离开，供应商收现金，资产火灾出售，以及 Myers（1977）已经点名的债务积压——正 NPV 项目因为新股权先给债权人打工而被放弃。Andrade 与 Kaplan（1998）用高杠杆交易后陷入困境、但事前并非经营失败的样本，试图把<strong>财务困境</strong>从经济困境里分开。缺口是权衡左边的税盾已经有公式，右边必须可拆，而不是一个残差口袋。</p><p><span class="marginnote">「债务积压」的白话版：公司欠债太多，赚了钱先归债主，股东掏钱投资新项目等于替别人打工，于是连好项目也懒得投——就像房子快要被收走的人，不会再花钱修屋顶。</span></p><p><span class="marginnote">直接成本：破产程序里的法律、会计、法院费用，以及资产在程序中的额外损耗。间接成本：违约或近违约改变了经营现金流本身。评级下调是信息，不是成本；成本是随后的真实行为。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把权衡写成</p> \\[V_L = V_U + \\mathrm{PV}(\\text{税盾}) - \\mathrm{PV}(\\text{直接}) - \\mathrm{PV}(\\text{间接}). \\]<p>直接项随程序启动的概率与程序费用上升，是事件成本。间接项随杠杆与距违约距离上升，是路径成本，不必等到立案。Kraus–Litzenberger 的状态惩罚可以两套都装：有的状态付律师费，有的状态付「客户走了」。</p><p><span class="marginnote">数字实例：Warner 度量的直接破产费用往往只占公司价值的百分之几；而对一家九成靠债的企业，客户流失让经营现金流掉一成，价值损失就可能超过全部律师费——间接项比直接项大一个量级，这才是真正挡住税盾的那只手。</span></p><p>Andrade–Kaplan 的识别策略是理论课要保留的那一句：找财务杠杆过高、核心经营未必坏的企业，看困境期间的价值损失有多大。本课不审他们的点估计，只取分类——财务困境可以单独昂贵。Warner 的直接成本小，则预测：真正挡住 \\(\\tau_c D\\) 的，主要是间接项。</p>',14)),(r(),B(l,null,{default:n(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIST%5B%22%E5%9B%B0%E5%A2%83%E6%88%90%E6%9C%AC%E7%8E%B0%E5%80%BC%22%5D%20--%3E%20DIR%5B%22%E7%9B%B4%E6%8E%A5%3A%20%E6%B3%95%E5%BE%8B%E4%B8%8E%E7%A8%8B%E5%BA%8F%22%5D%0A%20%20DIST%20--%3E%20IND%5B%22%E9%97%B4%E6%8E%A5%3A%20%E5%AE%A2%E6%88%B7%E9%9B%87%E5%91%98%E6%8A%95%E8%B5%84%22%5D%0A%20%20DIR%20--%3E%20WARN%5B%22Warner%3A%20%E5%BE%80%E5%BE%80%E5%BE%88%E5%B0%8F%22%5D%0A%20%20IND%20--%3E%20AK%5B%22Andrade-Kaplan%3A%20%E8%B4%A2%E5%8A%A1%E5%9B%B0%E5%A2%83%E5%8F%AF%E8%B4%B5%22%5D%0A%20%20IND%20--%3E%20OV%5B%22%E5%80%BA%E5%8A%A1%E7%A7%AF%E5%8E%8B%E4%B8%8E%E8%B5%84%E4%BA%A7%E6%9B%BF%E4%BB%A3%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"资产替代（赌大的）与投资不足都是事前间接成本：它们改变项目分布，不进破产账单。权衡若只盯立案费用，会漏掉杠杆在「尚未破产」时已经做的事。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("机制是控制权转移与经营互补。直接成本是转移时的摩擦：法庭是一种配置技术，收费。间接成本是转移"),E("strong",null,"被预期"),e("时，互补的专用性投资停止——客户、雇员、供应商不愿把准租金交给可能易主的企业。这与"),E("a",{href:"/econ/control-rights"},"不完全合同"),e("后课的控制权语言衔接，本课只从权衡右边引入：杠杆提高控制权转移概率，于是专用性投资下降，价值在立案前就掉。")],-1)),(r(),B(l,null,{default:n(()=>[i(t,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%9D%A0%E6%9D%86%E5%8D%87%E9%AB%98%22%5D%20--%3E%20P%5B%22%E8%BF%9D%E7%BA%A6%E6%A6%82%E7%8E%87%E8%A2%AB%E5%B8%82%E5%9C%BA%E9%A2%84%E6%9C%9F%22%5D%0A%20%20P%20--%3E%20CU%5B%22%E5%AE%A2%E6%88%B7%E4%B8%8D%E6%95%A2%E4%B8%8B%E9%95%BF%E6%9C%9F%E8%AE%A2%E5%8D%95%22%5D%0A%20%20P%20--%3E%20EM%5B%22%E5%A5%BD%E9%9B%87%E5%91%98%E6%8F%90%E5%89%8D%E8%B7%B3%E6%A7%BD%22%5D%0A%20%20P%20--%3E%20SU%5B%22%E4%BE%9B%E5%BA%94%E5%95%86%E8%A6%81%E6%B1%82%E7%8E%B0%E6%AC%BE%E7%8E%B0%E8%B4%A7%22%5D%0A%20%20CU%20--%3E%20Q%5B%22%E7%BB%8F%E8%90%A5%E7%8E%B0%E9%87%91%E6%B5%81%E5%9C%A8%E7%AB%8B%E6%A1%88%E5%89%8D%E5%B0%B1%E7%BC%A9%E6%B0%B4%22%5D%0A%20%20EM%20--%3E%20Q%0A%20%20SU%20--%3E%20Q%0A%20%20Q%20--%3E%20V%5B%22%E4%BB%B7%E5%80%BC%E6%8D%9F%E5%A4%B1%20%3D%20%E9%97%B4%E6%8E%A5%E5%9B%B0%E5%A2%83%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>火灾出售把流动性问题做成价格冲击，与银行课的清算折扣同构，对象换成非金融资产。间接成本因此可以有宏观外部性；私人 \\(D^\\ast\\) 仍可能高于社会最优。那一层已经在资本监管出现过，这里不重开银行。</p><h3 id="不要把经营失败叫成破产成本" tabindex="-1">不要把经营失败叫成破产成本 <a class="header-anchor" href="#不要把经营失败叫成破产成本" aria-label="Permalink to &quot;不要把经营失败叫成破产成本&quot;">​</a></h3><p>经济困境：产品没人要，即使全股权也会收缩。财务困境：资本结构使本来可过下去的经营触发违约。权衡要减的是后者。把衰退里的亏损全部记成「破产成本」，会把税盾权衡做成周期残差。Andrade–Kaplan 标题里的 not economic 就是这道过滤器。</p><p><span class="marginnote">间接成本难以从利润表的某一行读出。它是反事实：若杠杆更低，客户是否仍在。这使右边比 \\(\\tau_c D\\) 更难审计，不使它更不真实。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用直接成本的「小」否证权衡：否证的是「只有律师费」的版本。也不要把优序的发股折价算进破产成本——柠檬是发行市场的信息，下一课才用。Jensen 的债务纪律与间接成本方向相反，代理现金放到<a href="/econ/agency-free-cash-flow">自由现金流</a>，以免权衡被撑成万能袋。</p><p>本课不估计行业平均困境成本百分比。后课默认：权衡右边以间接为主，直接往往不够挡税盾；债务积压与资产替代算事前间接。优序解释的是朝 \\(D^\\ast\\) 调整为何贵，不是把 \\(D^\\ast\\) 拆开。</p><p>Warner 的小数是对程序费用。把它当成「破产便宜所以应当全债」，漏了客户与投资。</p><p><span class="marginnote">常见误区：看到「直接破产成本很小」的研究，就推出「企业应当把杠杆拉满」。那只覆盖律师费；真正约束杠杆的是客户、雇员与投资机会在违约之前就开始撤离。把「破产便宜」读成「全债最优」，是这一课最贵的误读。</span></p><p>财务困境可以发生在核心产品仍然有需求的时候。那才是资本结构的成本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>权衡的困境成本必须拆：直接程序费用 vs 间接经营与激励。</li><li>Warner：直接成本往往小；挡住税盾的主要是间接项。</li><li>Andrade–Kaplan：财务困境（相对经济困境）可以单独昂贵。</li><li>出处：Warner, <em>Journal of Finance</em> 1977；Andrade and Kaplan, <em>Journal of Finance</em> 1998。</li></ul>',12))])}const C=s(d,[["render",c]]);export{b as __pageData,C as default};
